import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { NewItem } from 'src/app/models/new-item.model';

@Injectable({
  providedIn: 'root',
})
export class UserItemService {
  private apiUrl = 'http://localhost:8080/api/user/items';

  constructor(private http: HttpClient) {}

  getAllItems(): Observable<NewItem[]> {
    return this.http.get<NewItem[]>(this.apiUrl);
  }

  getItemById(id: number): Observable<NewItem> {
    return this.http.get<NewItem>(`${this.apiUrl}/${id}`);
  }

  buyItem(id: number): Observable<any> {
    return this.http.post(`${this.apiUrl}/buy/${id}`, {});
  }
}
